"""UI kit of the menu theme: the drawing pieces of Flux's menus (pictures generated by gen_ui.py and auto_bg.py).

Inventory style (2026-11-15, replaces the grey vanilla window of 2026-10-29): every piece is taken from the server's
player inventory texture (inventory_style.png, copy of influstatique's gui/container/inventory.png): its frame and
ornate corners, its textured ground, its separator line. A tall plate holds the title (white, 1 px shadow, as every
text); content stands on the ground, never on a slot tile; groups of content sit in dark wells (rounded, black edge,
shade line under), 1 px off any button right next to them. Owner's corrections of 2026-11-15 on /menu2, /metiers and
the market, see docs/technique/flux-ui.md.
Pieces, in window pixels (176 x 221, item of a slot at fond_lib.objet(slot)):
  title(im, txt)                       text on the title plate
  slot(d, case, kind)                  vanilla | dark | lit (selected) | colour cell
  container(im, d, box, style, ...)    sub-container: ardoise | encre | puits | carte | verre, header strip/tab/label
  button(d, box, colour, icon)         button of the reference: black outline, bevel, white line under the bottom edge
  field(d, box, ...)                   dark display (value, page "1/2")
  bar(d, box, pct, colour)             progress bar
"""
import os
import sys

from PIL import Image, ImageDraw

sys.path.insert(0, "/home/influencraft/plugins/fluxplugin/Flux/assets")
import fond_lib  # noqa: E402
from fond_lib import objet  # noqa: E402

fond_lib._EXTRA.update({
    "/": ["..#", "..#", ".#.", "#..", "#.."], "%": ["#.#", "..#", ".#.", "#..", "#.#"], ".": [".", ".", ".", ".", "#"],
    ":": [".", "#", ".", "#", "."], "+": ["...", ".#.", "###", ".#.", "..."], "·": [".", ".", "#", ".", "."],
})

W, H = 176, 221
BLACK = (0, 0, 0, 255)
WHITE = (255, 255, 255, 255)
BODY = (198, 198, 198, 255)
SHADE = (85, 85, 85, 255)
SLOT = (139, 139, 139, 255)
SLOT_DARK = (55, 55, 55, 255)
INK = (64, 64, 64, 255)
LIGHT_TEXT = (230, 230, 230, 255)


def rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4)) + (255,)


def tone(c, f):
    if f >= 0:
        return tuple(round(c[i] + (255 - c[i]) * f) for i in range(3)) + (255,)
    return tuple(round(c[i] * (1 + f)) for i in range(3)) + (255,)


# ---------------------------------------------------------------- inventory style (2026-11-15)

INVENTORY = os.path.join(os.path.dirname(os.path.abspath(__file__)), "inventory_style.png")
OUTLINE = (21, 17, 27, 255)       # black edge of every piece
EDGE = (127, 102, 163, 255)       # light purple line of the frame
CELL = (89, 70, 116, 255)         # slot colour of the inventory (raised faces: pager buttons)
GROUND = (44, 35, 57, 255)        # ground of the window
WELL = (25, 20, 32, 255)          # inside of a well (player model box of the inventory)
SHADE_LINE = (58, 46, 76, 255)    # line under a well, strips
RAISED = (71, 56, 92, 255)        # raised card
TEXT_SHADOW_DARK = OUTLINE
_INV = None


def inventory():
    global _INV
    if _INV is None:
        _INV = Image.open(INVENTORY).convert("RGBA")
    return _INV


def ground(w, h):
    """The textured ground of the inventory, tiled (a 32 x 16 plain piece of it)."""
    t = inventory().crop((133, 4, 165, 20))
    out = Image.new("RGBA", (w, h))
    for y in range(0, h, t.height):
        for x in range(0, w, t.width):
            out.paste(t, (x, y))
    return out


def panel(w, h, e=7):
    """A window of w x h in the inventory's frame: its corners, its borders repeated, its ground (9-slice)."""
    inv = inventory()
    im = ground(w, h)
    im.paste(inv.crop((0, 0, e, e)), (0, 0))
    im.paste(inv.crop((176 - e, 0, 176, e)), (w - e, 0))
    im.paste(inv.crop((0, 166 - e, e, 166)), (0, h - e))
    im.paste(inv.crop((176 - e, 166 - e, 176, 166)), (w - e, h - e))
    top, bot = inv.crop((40, 0, 56, e)), inv.crop((40, 166 - e, 56, 166))
    for x in range(e, w - e, 16):
        cw = min(16, w - e - x)
        im.paste(top.crop((0, 0, cw, e)), (x, 0))
        im.paste(bot.crop((0, 0, cw, e)), (x, h - e))
    left, right = inv.crop((0, 20, 4, 36)), inv.crop((172, 20, 176, 36))
    for y in range(e, h - e, 16):
        ch = min(16, h - e - y)
        im.paste(left.crop((0, 0, 4, ch)), (0, y))
        im.paste(right.crop((0, 0, 4, ch)), (w - 4, y))
    return im


def separator(im, y):
    """The inventory's separator line (diamond ends), the window's full width."""
    im.alpha_composite(inventory().crop((0, 137, 176, 140)), (0, y))


PLATE_X, PLATE_W = 44, 88


def plate_box(top):
    """Title plate of a window whose frame starts at y = top: 15 px above it (less when the picture has no room),
    6 px into it."""
    return max(0, top - 15), top + 6


def plate_text_y(top):
    p0, p1 = plate_box(top)
    return (p0 + p1) // 2 - 2


def styled_window(top, bottom, title=None):
    """The window from y = top to y = bottom (inclusive) on a 176 x 221 picture, its plate, the title written on it."""
    im = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    im.alpha_composite(panel(W, bottom - top + 1), (0, top))
    p0, p1 = plate_box(top)
    im.alpha_composite(panel(PLATE_W, p1 - p0 + 1), (PLATE_X, p0))
    if title:
        write(im, title, 88, plate_text_y(top), WHITE, OUTLINE)
    return im


def well(d, box):
    """Dark well around a group of content: rounded, black edge, shade line under it."""
    x0, y0, x1, y1 = box
    d.rounded_rectangle(box, radius=3, fill=WELL, outline=OUTLINE)
    d.line((x0 + 3, y1 + 1, x1 - 3, y1 + 1), fill=SHADE_LINE)


def window(generic=None):
    """The full window (rows 0 to the hotbar) in the inventory style. ``generic`` is no longer read (grey window of
    the former theme)."""
    return styled_window(7, H - 1)

def write(im, txt, cx, y, colour, shadow=None, left=None):
    """QuinqueFive capitals centred on cx (or starting at left), optional shadow (None = flat)."""
    x = left if left is not None else cx - fond_lib.text_width(txt) // 2
    px = im.load()
    for c in txt.upper():
        g, extra = fond_lib._glyph(c)
        if not g:
            x += 4
            continue
        for dy, row in enumerate(g):
            for dx, ch in enumerate(row):
                if ch == "#":
                    if shadow:
                        px[x + dx, y + dy + 1] = shadow
        for dy, row in enumerate(g):
            for dx, ch in enumerate(row):
                if ch == "#":
                    px[x + dx, y + dy] = colour
        for dx, dy in extra:
            px[x + dx, y + dy] = colour
        x += len(g[0]) + 1
    return x


def title(im, txt):
    write(im, txt, 88, 4, INK)


def slot_box(case, rows=6):
    x, y = objet(case, rows)
    return x - 1, y - 1, x + 16, y + 16


def slot(d, case, kind="vanilla", colour=None, rows=6):
    """rows: chest rows of the menu; under a smaller chest the inventory is higher in game."""
    x0, y0, x1, y1 = slot_box(case, rows)
    if kind in ("vanilla", "dark", "ink"):
        return            # inventory style: content stands on the ground or in its well, never on a slot tile
    if kind == "vanilla":
        base, tl, br = SLOT, SLOT_DARK, WHITE
    elif kind == "dark":
        base, tl, br = rgb("#4A4B50"), rgb("#2C2D31"), rgb("#6E6F75")
    elif kind == "ink":
        base, tl, br = rgb("#2B2B30"), rgb("#18181B"), rgb("#45454C")
    elif kind == "lit":        # selected: light raised cell
        base, tl, br = EDGE, tone(EDGE, 0.35), CELL
    else:                      # colour cell (highlight)
        base, tl, br = colour, tone(colour, -0.35), tone(colour, 0.35)
    d.rectangle((x0, y0, x1, y1), fill=base)
    d.line((x0, y0, x1 - 1, y0), fill=tl)
    d.line((x0, y0, x0, y1 - 1), fill=tl)
    d.line((x0 + 1, y1, x1, y1), fill=br)
    d.line((x1, y0 + 1, x1, y1), fill=br)


def outline_cell(d, case, colour=WHITE):
    x0, y0, x1, y1 = slot_box(case)
    d.rectangle((x0 - 1, y0 - 1, x1 + 1, y1 + 1), outline=colour)


STYLES = {
    #           fill                  inner shadow           header band           header text
    "ardoise": (rgb("#585B5F"), rgb("#45474B"), rgb("#35363A"), LIGHT_TEXT),
    "encre": (rgb("#232327"), rgb("#141416"), rgb("#141416"), LIGHT_TEXT),
    "puits": (SLOT, SLOT_DARK, rgb("#6B6B6B"), WHITE),
    "carte": (rgb("#E4E4E4"), WHITE, rgb("#35363A"), LIGHT_TEXT),
    "verre": (rgb("#A9ABB0"), rgb("#8E9095"), rgb("#585B5F"), WHITE),
}


def container(im, d, box, style="ardoise", head=None, head_kind="strip", head_h=10, accent=None):
    """Sub-container: a dark well (every former style), or a raised card (carte). head_kind: strip (band inside the
    top), tab (tab above the left), label (text above). Texts white with their shadow."""
    x0, y0, x1, y1 = box
    if head and head_kind == "tab":
        tw = fond_lib.text_width(head) + 10
        d.rounded_rectangle((x0, y0 - head_h, x0 + tw, y0 + 2), radius=2, fill=accent or CELL, outline=OUTLINE)
        d.line((x0 + 2, y0 - head_h + 1, x0 + tw - 2, y0 - head_h + 1), fill=EDGE)
        write(im, head, 0, y0 - head_h + 3, WHITE, OUTLINE, left=x0 + 5)
    if style == "carte":       # raised card
        d.rounded_rectangle(box, radius=3, fill=RAISED, outline=OUTLINE)
        d.line((x0 + 3, y0 + 1, x1 - 3, y0 + 1), fill=EDGE)
        d.line((x0 + 3, y1 + 1, x1 - 3, y1 + 1), fill=SHADE_LINE)
    else:
        well(d, box)
    if head and head_kind == "strip":
        top = y0 + 1
        d.rectangle((x0 + 2, top, x1 - 2, top + head_h - 1), fill=accent or SHADE_LINE)
        d.line((x0 + 2, top + head_h, x1 - 2, top + head_h), fill=OUTLINE)
        write(im, head, (x0 + x1) // 2, top + (head_h - 5) // 2, WHITE, OUTLINE)
    if head and head_kind == "label":
        write(im, head, 0, y0 - 8, WHITE, OUTLINE, left=x0 + 1)


def button(d, box, colour, icon=None, label=None, im=None):
    """Reference button: black outline, light top-left edge, darker bottom, white line under the bottom outline."""
    x0, y0, x1, y1 = box
    d.rectangle(box, fill=BLACK)
    d.rectangle((x0 + 1, y0 + 1, x1 - 1, y1 - 1), fill=tone(colour, 0.45))
    d.rectangle((x0 + 2, y0 + 2, x1 - 1, y1 - 1), fill=tone(colour, -0.25))
    d.rectangle((x0 + 2, y0 + 2, x1 - 2, y1 - 3), fill=colour)
    d.line((x0 + 1, y1 + 1, x1 - 1, y1 + 1), fill=SHADE_LINE)     # shade under it on the dark window
    cx, cy = (x0 + x1) // 2, (y0 + y1) // 2 - 1
    if icon:
        ICONS[icon](d, cx, cy)
    if label and im is not None:
        write(im, label, cx + 1, cy - 2, WHITE, tone(colour, -0.55))


def button_slot(d, case, colour, icon):
    x, y = objet(case)
    button(d, (x - 1, y - 1, x + 16, y + 15), colour, icon)


def _px(d, pts, cx, cy, c=WHITE, sh=(0, 0, 0, 140)):
    for x, y in pts:
        d.point((cx + x + 1, cy + y + 1), fill=sh)
    for x, y in pts:
        d.point((cx + x, cy + y), fill=c)


def _arrow(sign):
    def f(d, cx, cy):
        pts = [(sign * i, j) for i in range(-3, 4) for j in (-1, 0)]
        pts += [(sign * -3 + sign * k, j) for k in range(0, 4) for j in range(-k - 1, k + 1) if abs(j + 0.5) <= 3.5 - k]
        _px(d, set(pts), cx, cy)
    return f


def _cross(d, cx, cy):
    _px(d, [(i, i) for i in range(-3, 4)] + [(i, -i) for i in range(-3, 4)] + [(i + 1, i) for i in range(-3, 3)] + [(i + 1, -i) for i in range(-3, 4)], cx, cy)


def _info(d, cx, cy):
    _px(d, [(0, -4), (1, -4), (0, -2), (1, -2)] + [(x, y) for x in (0, 1) for y in range(-1, 4)] + [(-1, 3), (2, 3)], cx, cy)


def _check(d, cx, cy):
    _px(d, [(-3, 0), (-2, 1), (-1, 2), (0, 1), (1, 0), (2, -1), (3, -2), (-3, 1), (-2, 2), (-1, 3), (0, 2), (1, 1), (2, 0), (3, -1)], cx, cy)


def _plus(d, cx, cy):
    _px(d, [(i, j) for i in range(-3, 4) for j in (0, 1)] + [(j, i) for i in range(-3, 4) for j in (0, 1) if i not in (0, 1)], cx, cy)


def _back(d, cx, cy):
    _px(d, [(-3, 0), (-2, -1), (-2, 1), (-1, -2), (-1, 2)] + [(i, 0) for i in range(-2, 4)] + [(3, -1), (3, -2), (3, -3)], cx, cy)


ICONS = {"left": _arrow(1), "right": _arrow(-1), "close": _cross, "info": _info, "check": _check, "plus": _plus, "back": _back}


def field(im, d, box, txt="", colour=WHITE, align="center", style="ink"):
    """Dark display (value, name): a well, text white with its shadow."""
    x0, y0, x1, y1 = box
    well(d, box)
    if txt:
        ty = (y0 + y1) // 2 - 2
        if align == "center":
            write(im, txt, (x0 + x1) // 2 + 1, ty, colour, OUTLINE)
        else:
            write(im, txt, 0, ty, colour, OUTLINE, left=x0 + 4)


def bar(d, box, pct, colour):
    x0, y0, x1, y1 = box
    d.rounded_rectangle(box, radius=2, fill=WELL, outline=OUTLINE)
    w = round((x1 - x0 - 2) * pct)
    if w > 0:
        d.rectangle((x0 + 1, y0 + 1, x0 + w, y1 - 1), fill=colour)
        d.line((x0 + 1, y0 + 1, x0 + w, y0 + 1), fill=tone(colour, 0.4))
        d.line((x0 + 1, y1 - 1, x0 + w, y1 - 1), fill=tone(colour, -0.3))
    d.line((x0 + 2, y1 + 1, x1 - 2, y1 + 1), fill=SHADE_LINE)


def flat_button(d, box, icon, on=True):
    """Pager button: raised like an inventory slot, light arrow (dark when there is no page that way)."""
    x0, y0, x1, y1 = box
    d.rounded_rectangle(box, radius=3, fill=CELL if on else RAISED, outline=OUTLINE)
    d.line((x0 + 3, y0 + 1, x1 - 3, y0 + 1), fill=EDGE if on else CELL)
    d.line((x0 + 3, y1 - 1, x1 - 3, y1 - 1), fill=SHADE_LINE)
    cx, cy = (x0 + x1 + 1) // 2, (y0 + y1) // 2
    pts = [(cx + 2, cy - 3), (cx - 1, cy), (cx + 2, cy + 3)] if icon == "left" else [(cx - 2, cy - 3), (cx + 1, cy), (cx - 2, cy + 3)]
    d.polygon(pts, fill=(236, 226, 250, 255) if on else SHADE_LINE)


def item(im, case, png, dx=0, dy=0):
    if png is None or not os.path.exists(png):
        return
    tex = Image.open(png).convert("RGBA")
    if tex.size != (16, 16):
        tex = tex.resize((16, 16), Image.LANCZOS if tex.width > 16 else Image.NEAREST)
    x, y = objet(case)
    im.alpha_composite(tex, (x + dx, y + dy))


def portrait(im, png, x, y):
    im.alpha_composite(Image.open(png).convert("RGBA").resize((64, 64), Image.NEAREST), (x, y))
